def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 4 != 0 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[1:] + [filtered_rows[0]] if len(filtered_rows) > 1 else filtered_rows

    eligible_days = []
    for row in rotated_rows:
        day, is_blackout = row
        if not is_blackout and day % 5 != 0:
            eligible_days.append(day)

    distinct_days = sorted(list(set(eligible_days)))[:2]
    return distinct_days

